1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { lstatSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	import {
7	  FIELD_LIMITS,
8	  checkIdeaContent,
9	  isCompleteIdea,
10	  normalizeIdea,
11	  fieldRulesBrowserScript,
12	  type ContentErrorCode,
13	} from './idea-fields.ts';
14	
15	const PRODUCT: string = 'FeatureHarbor';
16	const RESOURCE: string = 'ideas';
17	const MAX_BODY_BYTES = 1_000_000;
18	// 严格 UTF-8 解码器：fatal 模式遇到非法字节直接抛错，而不是像 Buffer.toString('utf8')
19	// 那样把坏字节静默替换成“�”。请求正文与磁盘上的已有意见都先在完整的字节缓冲上通过它，
20	// 才允许进入 JSON 解析；分段送达在缓冲拼接后判断，合法多字节字符被拆到相邻段不算损坏。
21	const UTF8_DECODER = new TextDecoder('utf-8', { fatal: true });
22	// 接口侧把共用的内容判定结果映射成原有的错误说明；首页另有自己的措辞。
23	const CONTENT_ERROR_MESSAGES: Record<ContentErrorCode, string> = {
24	  'title-empty': '标题去掉首尾空白后不能为空',
25	  'title-too-long': `标题最多 ${FIELD_LIMITS.title} 个字符`,
26	  'description-empty': '详细说明必须包含非空白内容',
27	  'description-too-long': `详细说明最多 ${FIELD_LIMITS.description} 个字符`,
28	  'scenario-too-long': `使用场景最多 ${FIELD_LIMITS.scenario} 个字符`,
29	};
30	const PAGE: string = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeatureHarbor · 产品意见与公开路线图</title><style>
31	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
32	a{color:#175b9c}
33	label{display:block;font-weight:600;margin-top:1rem}
34	input,textarea{width:100%;box-sizing:border-box;padding:.4rem;font:inherit}
35	textarea{resize:vertical}
36	.required{color:#b00020}
37	button{margin-top:1rem;padding:.5rem 1.2rem;font:inherit}
38	#error{color:#b00020;margin-top:.75rem}
39	#success{color:#1a7f37;margin-top:.75rem}
40	.idea{border-top:1px solid #ddd;padding:1rem 0}
41	.idea h3{margin:0 0 .5rem}
42	.view-link{display:inline-block;margin-top:.5rem}
43	.pre{white-space:pre-wrap}
44	time{color:#666;font-size:.9rem}
45	#search-form{margin:1rem 0}
46	#search-form input{max-width:20rem;margin-right:.5rem}
47	#search-form button{margin-top:.25rem;margin-right:.5rem}
48	</style><main><h1>FeatureHarbor</h1><p>产品意见与公开路线图</p>
49	<h2>提交产品意见</h2>
50	<form id="idea-form" novalidate>
51	<label for="f-title">标题 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.title} 字）</label>
52	<input id="f-title" name="title" required>
53	<label for="f-desc">详细说明 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.description} 字）</label>
54	<textarea id="f-desc" name="description" rows="5" required></textarea>
55	<label for="f-scenario">使用场景（可选，最多 ${FIELD_LIMITS.scenario} 字）</label>
56	<textarea id="f-scenario" name="scenario" rows="3"></textarea>
57	<button type="submit">提交意见</button>
58	<p id="error" role="alert" hidden></p>
59	<p id="success" role="status" hidden></p>
60	</form>
61	<h2>意见列表</h2>
62	<form id="search-form" role="search" novalidate>
63	<label for="f-search">关键词搜索</label>
64	<input id="f-search" name="q" type="search" placeholder="搜索标题、详细说明或使用场景" autocomplete="off">
65	<button type="submit">搜索</button>
66	<button id="search-clear" type="button">清空</button>
67	</form>
68	<p id="empty" hidden>还没有意见记录。</p>
69	<div id="ideas"></div>
70	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
71	</main><script>
72	${fieldRulesBrowserScript}
73	const form = document.getElementById('idea-form');
74	const titleInput = document.getElementById('f-title');
75	const descInput = document.getElementById('f-desc');
76	const scenarioInput = document.getElementById('f-scenario');
77	const errorBox = document.getElementById('error');
78	const successBox = document.getElementById('success');
79	const emptyNote = document.getElementById('empty');
80	const list = document.getElementById('ideas');
81	const searchForm = document.getElementById('search-form');
82	const searchInput = document.getElementById('f-search');
83	const searchClear = document.getElementById('search-clear');
84	const EMPTY_TEXT = '还没有意见记录。';
85	const NOT_FOUND_TEXT = '没有找到符合关键词的意见。';
86	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
87	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
88	let listState = 'loading';
89	// 已生效的搜索关键词：去掉首尾空白后的完整一段文字，空字符串表示不搜索。
90	// 只影响当前页面的可见结果，不发起请求、不改变已保存记录与接口返回。
91	let activeKeyword = '';
92	// 纯文字的大小写不敏感包含判断：关键词内部空格按原文参与比较，
93	// 不拆词；标点、尖括号与看起来像正则表达式的文字都按普通文字查找，
94	// 因此直接用 includes，不能走正则。
95	function ideaMatches(idea, keyword) {
96	  const needle = keyword.toLowerCase();
97	  return idea.title.toLowerCase().includes(needle)
98	    || idea.description.toLowerCase().includes(needle)
99	    || idea.scenario.toLowerCase().includes(needle);
100	}
101	function showError(message) {
102	  errorBox.textContent = message;
103	  errorBox.hidden = false;
104	  successBox.hidden = true;
105	}
106	function renderIdea(idea) {
107	  const item = document.createElement('article');
108	  item.className = 'idea';
109	  const heading = document.createElement('h3');
110	  heading.textContent = idea.title;
111	  const desc = document.createElement('p');
112	  desc.className = 'pre';
113	  desc.textContent = idea.description;
114	  item.append(heading, desc);
115	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
116	    const scenario = document.createElement('p');
117	    const label = document.createElement('strong');
118	    label.textContent = '使用场景：';
119	    const text = document.createElement('span');
120	    text.className = 'pre';
121	    text.textContent = idea.scenario;
122	    scenario.append(label, text);
123	    item.append(scenario);
124	  }
125	  const time = document.createElement('time');
126	  time.dateTime = idea.createdAt;
127	  const parsed = new Date(idea.createdAt);
128	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
129	  item.append(time);
130	  // 每条已保存意见都有独立查看入口（搜索过滤后的结果与本页新提交同样带入口）：
131	  // 链接只由该记录的标识 id 决定，与标题、说明文字无关；id 经 encodeURIComponent
132	  // 编码，历史标识里的中文、空格或网址特殊字符也能准确指向自己的记录。
133	  // 历史标题可能为空，但入口不依赖标题，空标题记录仍可打开。
134	  const viewLink = document.createElement('a');
135	  viewLink.className = 'view-link';
136	  viewLink.href = '/ideas/' + encodeURIComponent(idea.id);
137	  viewLink.textContent = '查看这条意见';
138	  item.append(viewLink);
139	  return item;
140	}
141	let remoteIdeas = [];
142	// 本页已确认保存的意见，按本页发起提交的先后排列：后提交的在前。
143	// 每条记录带上点击提交时的序号，响应返回的先后不影响排列位置
144	const submittedIdeas = [];
145	function renderList() {
146	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
147	  const seen = new Set();
148	  const ordered = [];
149	  for (const entry of submittedIdeas) {
150	    const idea = entry.idea;
151	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
152	  }
153	  for (const idea of remoteIdeas) {
154	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
155	  }
156	  // 搜索只过滤当前页面的可见结果：沿用合并后的原有顺序，逐条判断、不去重不重排，
157	  // 同一条意见最多出现一次；匹配的意见仍按原文渲染（保留空白与换行），不删改内容。
158	  const visible = activeKeyword
159	    ? ordered.filter((idea) => ideaMatches(idea, activeKeyword))
160	    : ordered;
161	  list.replaceChildren(...visible.map(renderIdea));
162	  if (listState === 'failed') {
163	    // 加载失败优先显示现有的失败提示，不能把失败显示成搜索无结果
164	    emptyNote.textContent = LOAD_FAILED_TEXT;
165	    emptyNote.hidden = false;
166	  } else if (listState !== 'ready') {
167	    // 首次列表仍在加载，不能把等待误报成没有记录或没有匹配结果
168	    emptyNote.hidden = true;
169	  } else if (activeKeyword) {
170	    // 搜索已生效：完整列表是否为空决定提示措辞，已有意见但无匹配时明确提示未找到
171	    emptyNote.textContent = ordered.length === 0 ? EMPTY_TEXT : NOT_FOUND_TEXT;
172	    emptyNote.hidden = visible.length > 0;
