// 标题与说明相同但 id 不同的记录各自打开各自的页面。存储读取失败明确提示加载失败（500），
// 不能冒充不存在；能读取但找不到该 id 才提示该意见不存在（404），不展示其他意见。
function handleIdeaView(res: ServerResponse, rawPath: string): void {
