264	function assertArticleMatches(article: El, idea: Record<string, unknown>): void {
265	  const heading = article.children.find((n) => n.tagName === 'H3')!;
266	  assert.equal(heading.textContent, idea.title);
267	  const description = article.children.find((n) => n.tagName === 'P' && n.children.length === 0)!;
