273	    Boolean(scenarioNode),
274	    expectsScenario,
275	    `使用场景展示与否应与记录一致：${String(idea.scenario)}`,
276	  );
277	  if (expectsScenario) {
278	    const span = scenarioNode!.children.find((n) => n.tagName === 'SPAN')!;
