280	  }
281	  const time = article.children.find((n) => n.tagName === 'TIME')!;
282	  assert.equal(time.dateTime, idea.createdAt);
283	  // 每条意见都有独立查看入口：href 只由 id 经 encodeURIComponent 拼成，可直接分享
284	  const viewLink = findViewLink(article);
285	  assert.ok(viewLink, '每条意见都应有查看入口');
286	  assert.equal(viewLink!.href, `/ideas/${encodeURIComponent(String(idea.id))}`);
287	  assert.equal(viewLink!.textContent, '查看这条意见');
